CREATE TABLE IF NOT EXISTS library_lm_xv_kdp_fine_zones_v1 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES library_documents(id), document_code TEXT NOT NULL, source_run_id TEXT NOT NULL, structural_detector_run_id TEXT NOT NULL, fine_zone_run_id TEXT NOT NULL, pdf_page INT NOT NULL, printed_page INT, parent_block_id UUID REFERENCES library_lm_xv_kdp_page_blocks_v1(id), block_index INT, bbox JSONB, zone_type TEXT NOT NULL, zone_role TEXT NOT NULL, authority_level TEXT NOT NULL, text_quote TEXT NOT NULL, normalized_quote TEXT NOT NULL, quote_hash TEXT NOT NULL, confidence NUMERIC NOT NULL, evidence_origin TEXT NOT NULL, detection_rule TEXT NOT NULL, validation_status TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'not_required', warnings JSONB NOT NULL DEFAULT '[]', raw_detection JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(fine_zone_run_id,pdf_page,block_index)
);
CREATE INDEX IF NOT EXISTS idx_lm_xv_fz_page ON library_lm_xv_kdp_fine_zones_v1(pdf_page); CREATE INDEX IF NOT EXISTS idx_lm_xv_fz_type ON library_lm_xv_kdp_fine_zones_v1(zone_type); CREATE INDEX IF NOT EXISTS idx_lm_xv_fz_run ON library_lm_xv_kdp_fine_zones_v1(fine_zone_run_id);
CREATE OR REPLACE VIEW library_lm_xv_kdp_fine_zones_search_v1 AS SELECT * FROM library_lm_xv_kdp_fine_zones_v1;
CREATE OR REPLACE VIEW library_lm_xv_kdp_search_ready_v3 AS SELECT p.*,s.document_part,s.structural_status,s.unit_type,s.unit_label,f.id fine_zone_id,f.zone_type,f.zone_role,f.authority_level,f.text_quote,f.confidence,f.validation_status,f.warnings fine_zone_warnings FROM library_lm_xv_kdp_pages_v1 p JOIN library_lm_xv_kdp_structural_classifications_v1 s ON s.document_id=p.document_id AND s.pdf_page=p.pdf_page AND s.source_run_id=p.source_run_id LEFT JOIN library_lm_xv_kdp_fine_zones_v1 f ON f.document_id=p.document_id AND f.pdf_page=p.pdf_page AND f.source_run_id=p.source_run_id;
